import org.openenglish.reader.*;import org.json.*;import android.content.*;import java.util.*;
public final class JourneyTest {
 static int checks=0;static void check(boolean b,String reason){checks++;if(!b)throw new AssertionError(reason);}
 static class Memory extends Context implements SharedPreferences,SharedPreferences.Editor{Map<String,String> data=new HashMap<>();String k,v;public SharedPreferences getSharedPreferences(String n,int m){return this;}public String getString(String key,String fallback){return data.getOrDefault(key,fallback);}public Editor edit(){return this;}public Editor putString(String key,String value){k=key;v=value;return this;}public boolean commit(){data.put(k,v);return true;}}
 static JSONObject assessment(String body)throws Exception{return new JSONObject("{\"RecognitionStatus\":\"Success\",\"NBest\":["+body+"]}");}
 public static void main(String[] args)throws Exception{
  check(JourneyCore.nextStage(0,true,true)==1,"new recall moves to tomorrow");check(JourneyCore.nextStage(4,true,false)==4,"early repeat cannot advance");check(JourneyCore.nextStage(5,true,true)==5,"interval capped");check(JourneyCore.nextStage(4,false,true)==0,"failed recall resets");check(JourneyCore.nextDue(100,0)==600100,"failed recall ten minutes");check(JourneyCore.nextDue(100,5)==100+30*JourneyCore.DAY,"30 day due");
  check(JourneyCore.difference("Hello, I'm Mei!","hello i'm mei").contains("不代表"),"matching ASR never certifies phones");check(JourneyCore.difference("I need water","I water").contains("未识别到：need"),"word omission");check(JourneyCore.difference("I need water","I need some water").contains("额外识别：some"),"word insertion");check(JourneyCore.difference("Turn right","turn light").contains("right → 识别为 light"),"word substitution");check(JourneyCore.difference("hello","").contains("没有识别"),"empty ASR");check(JourneyCore.phoneTip("TH").contains("不振动"),"SAPI th guidance");check(JourneyCore.phoneTip("ð").contains("振动"),"IPA guidance");
  check(!JourneyFeedback.parse(new JSONObject()).usable,"missing result not scored");check(!JourneyFeedback.parse(assessment("{}" )).usable,"missing scores not zero");
  check(!JourneyFeedback.parse(assessment("{\"PronunciationAssessment\":{\"AccuracyScore\":101}}" )).usable,"invalid score not accepted");
  JourneyFeedback zero=JourneyFeedback.parse(assessment("{\"PronunciationAssessment\":{\"AccuracyScore\":0}}"));check(zero.usable&&zero.accuracy==0,"real zero retained");
  JourneyFeedback f=JourneyFeedback.parse(assessment("{\"PronunciationAssessment\":{\"AccuracyScore\":68,\"FluencyScore\":71},\"Words\":[{\"Word\":\"think\",\"Phonemes\":[{\"Phoneme\":\"th\",\"PronunciationAssessment\":{\"AccuracyScore\":40}}]},{\"Word\":\"again\",\"PronunciationAssessment\":{\"ErrorType\":\"Omission\"}}]}"));check(f.usable&&f.text.contains("/th/")&&f.text.contains("不振动"),"real low phone coached");check(f.text.contains("漏读：again"),"miscue retained");check(!f.text.contains("完整度 0"),"missing completeness not invented");
  JourneyState s=new JourneyState(new Memory());s.practice("u01",0,"识别对照",false);s.practice("u01",1,"真实音素评测",true);s.practice("u01",2,"回听",false);check(!s.complete("u01"),"speaking alone not completed");s.mark("u01","heard",7);check(!s.complete("u01"),"listening and recording still need recall");long now=System.currentTimeMillis();for(int i=0;i<3;i++)s.recall("u01_"+i,true,now);check(s.complete("u01"),"completed evidence recorded");long due=s.card("u01_0").getLong("due");s.recall("u01_0",true,now+100);check(s.card("u01_0").getInt("stage")==1&&s.card("u01_0").getLong("due")==due,"early repeat neither advances nor postpones");s.recall("u01_0",false,now+200);check(!s.complete("u01"),"failed recall reopens unit");check(s.card("u01_0").getLong("due")==now+200+600000,"failure due");check(s.due(now+601000).contains("u01_0"),"due review visible");
  for(int i=0;i<40;i++)s.message("u01",i%2==0?"user":"assistant","Message "+i);check(s.chat("u01").length()==30,"chat bounded");check(s.chat("u01").getJSONObject(0).getString("content").equals("Message 10"),"most recent messages retained");
  String exported=s.export();JourneyState restored=new JourneyState(new Memory());restored.restore(exported);check(restored.export().equals(exported),"backup round trip");boolean rejected=false;try{restored.restore("{\"schema\":99}");}catch(Exception e){rejected=true;}check(rejected&&restored.export().equals(exported),"invalid restore preserves state");
  JSONObject invalid=new JSONObject(exported);invalid.getJSONObject("cards").put("u99_4",new JSONObject());rejected=false;try{restored.restore(invalid.toString());}catch(Exception e){rejected=true;}check(rejected,"unknown course rejected");
  String compact=JourneyCore.tutorInstruction(5,String.join("",Collections.nCopies(80,"话")),String.join("",Collections.nCopies(200,"a")));
  check(compact.length()<=600,"local tutor instructions survive 600-character engine cap");check(compact.contains("Never judge pronunciation")&&compact.contains("40-90"),"local prompt retains feedback limits and advanced style");
  s.message("u01","assistant",String.join("",Collections.nCopies(12000,"字")));check(s.chat("u01").getJSONObject(29).getString("content").length()<=1500,"stored replies bounded with explicit truncation");
  JSONObject largest=new JSONObject(s.export());JSONObject allChats=new JSONObject();String chinese=String.join("",Collections.nCopies(1500,"字"));
  for(int u=1;u<=48;u++){JSONArray a=new JSONArray();for(int m=0;m<30;m++)a.put(new JSONObject().put("role","user").put("content",chinese));allChats.put(String.format(Locale.US,"u%02d",u),a);}largest.put("chats",allChats);
  JourneyState.validate(largest);check(largest.toString().getBytes("UTF-8").length<10000000,"all 48 full Chinese conversations fit the import byte ceiling");
  System.out.println("Journey checks: "+checks);
 }
}
